# generate-thrown-and-caught.py <outdir>: an object is thrown by one road, whoever catches it does ONE DEED to it, and the thrower then uses the object as what it is.
# What is thrown does not escape by itself: every road by which a thrown value comes to a handler must be a road of Link's, or the value must escape on it.
# road x deed x use. Every program prints what plain Bun prints.
import sys, os
out = sys.argv[1]
os.makedirs(out, exist_ok=True)

# Each road: lines that define `async function road(p, deed)`: p is thrown somewhere, caught somewhere, and deed(e) is called with what was caught.
roads = {
 'in-the-block':            'try { throw p; } catch (e) { deed(e); }',
 'in-a-callee':             'function thrower(v) { throw v; }\n  try { thrower(p); } catch (e) { deed(e); }',
 'two-callees-down':        'function inner(v) { throw v; }\n  function outer(v) { inner(v); }\n  try { outer(p); } catch (e) { deed(e); }',
 'caught-by-the-caller':    'function inner(v) { throw v; }\n  function middle(v) { try { inner(v); } finally { count++; } }\n  try { middle(p); } catch (e) { deed(e); }',
 'rethrown':                'function inner(v) { try { throw v; } catch (e) { throw e; } }\n  try { inner(p); } catch (e) { deed(e); }',
 'nested-handlers':         'try { try { throw p; } catch (e) { throw e; } } catch (e) { deed(e); }',
 'thrown-in-a-handler':     'try { try { throw 1; } catch (e) { throw p; } } catch (e) { deed(e); }',
 'thrown-in-finally':       'try { try { count++; } finally { throw p; } } catch (e) { deed(e); }',
 'by-a-method':             'const o = { m(v) { throw v; } };\n  try { o.m(p); } catch (e) { deed(e); }',
 'by-a-method-of-a-class':  'class T { m(v) { throw v; } }\n  try { new T().m(p); } catch (e) { deed(e); }',
 'by-a-static-method':      'class T { static m(v) { throw v; } }\n  try { T.m(p); } catch (e) { deed(e); }',
 'by-a-value-called':       'const fs = [v => { throw v; }, v => v];\n  try { fs[count](p); } catch (e) { deed(e); }',
 'by-a-getter':             'const o = { get g() { throw p; } };\n  try { o.g; } catch (e) { deed(e); }',
 'by-a-getter-of-a-class':  'class T { get g() { throw p; } }\n  try { new T().g; } catch (e) { deed(e); }',
 'by-a-setter':             'const o = { set s(v) { throw v; } };\n  try { o.s = p; } catch (e) { deed(e); }',
 'by-a-defined-getter':     'const o = Object.defineProperty({}, "g", { get: function () { throw p; } });\n  try { o.g; } catch (e) { deed(e); }',
 'by-value-of':             'const o = { valueOf() { throw p; } };\n  try { o + 1; } catch (e) { deed(e); }',
 'by-to-string':            'const o = { toString() { throw p; } };\n  try { `${o}`; } catch (e) { deed(e); }',
 'by-to-primitive':         'const o = { [Symbol.toPrimitive]() { throw p; } };\n  try { o * 2; } catch (e) { deed(e); }',
 'by-a-key-conversion':     'const o = { toString() { throw p; } };\n  try { ({})[o]; } catch (e) { deed(e); }',
 'by-a-comparison':         'const o = { valueOf() { throw p; } };\n  try { o < 1; } catch (e) { deed(e); }',
 'by-next':                 'const o = { [Symbol.iterator]() { return { next() { throw p; } }; } };\n  try { for (const x of o) count++; } catch (e) { deed(e); }',
 'by-the-iterator-method':  'const o = { [Symbol.iterator]() { throw p; } };\n  try { [...o]; } catch (e) { deed(e); }',
 'by-return-of-an-iterator': 'const o = { [Symbol.iterator]() { return { next() { return { done: false, value: 1 }; }, return() { throw p; } }; } };\n  try { for (const x of o) break; } catch (e) { deed(e); }',
 'by-destructuring':        'const o = { get g() { throw p; } };\n  try { const { g } = o; } catch (e) { deed(e); }',
 'by-a-default-value':      'function f(a = (() => { throw p; })()) {}\n  try { f(); } catch (e) { deed(e); }',
 'by-a-constructor':        'class T { constructor(v) { throw v; } }\n  try { new T(p); } catch (e) { deed(e); }',
 'by-a-base-constructor':   'class B { constructor(v) { throw v; } }\n  class T extends B {}\n  try { new T(p); } catch (e) { deed(e); }',
 'by-a-field-initializer':  'class T { f = (() => { throw p; })(); }\n  try { new T(); } catch (e) { deed(e); }',
 'by-a-static-block':       'try { class T { static { throw p; } } } catch (e) { deed(e); }',
 'by-a-heritage':           'try { class T extends (() => { throw p; })() {} } catch (e) { deed(e); }',
 'by-a-constructor-function': 'function T(v) { throw v; }\n  try { new T(p); } catch (e) { deed(e); }',
 'by-a-tag':                'function tag() { throw p; }\n  try { tag`a`; } catch (e) { deed(e); }',
 'by-map':                  'try { [1].map(() => { throw p; }); } catch (e) { deed(e); }',
 'by-for-each':             'try { [p].forEach(v => { throw v; }); } catch (e) { deed(e); }',
 'by-sort':                 'try { [1, 2].sort(() => { throw p; }); } catch (e) { deed(e); }',
 'by-replace':              'try { "a".replace("a", () => { throw p; }); } catch (e) { deed(e); }',
 'by-a-reviver':            'try { JSON.parse("1", () => { throw p; }); } catch (e) { deed(e); }',
 'by-to-json':              'try { JSON.stringify({ toJSON() { throw p; } }); } catch (e) { deed(e); }',
 'by-array-from':           'try { Array.from([1], () => { throw p; }); } catch (e) { deed(e); }',
 'by-reduce':               'try { [1, 2].reduce(() => { throw p; }); } catch (e) { deed(e); }',
 'by-map-for-each':         'try { new Map([[1, p]]).forEach(v => { throw v; }); } catch (e) { deed(e); }',
 'by-call':                 'function thrower(v) { throw v; }\n  try { thrower.call(null, p); } catch (e) { deed(e); }',
 'by-apply':                'function thrower(v) { throw v; }\n  try { thrower.apply(null, [p]); } catch (e) { deed(e); }',
 'by-bind':                 'function thrower(v) { throw v; }\n  try { thrower.bind(null, p)(); } catch (e) { deed(e); }',
 'by-reflect-apply':        'function thrower(v) { throw v; }\n  try { Reflect.apply(thrower, null, [p]); } catch (e) { deed(e); }',
 'by-reflect-construct':    'class T { constructor(v) { throw v; } }\n  try { Reflect.construct(T, [p]); } catch (e) { deed(e); }',
 'by-a-proxy-trap':         'const o = new Proxy({}, { get() { throw p; } });\n  try { o.x; } catch (e) { deed(e); }',
 'by-a-proxied-function':   'const f = new Proxy(function () {}, { apply() { throw p; } });\n  try { f(); } catch (e) { deed(e); }',
 'by-an-executor':          'try { await new Promise(() => { throw p; }); } catch (e) { deed(e); }',
 'by-reject':               'try { await new Promise((resolve, reject) => reject(p)); } catch (e) { deed(e); }',
 'by-promise-reject':       'try { await Promise.reject(p); } catch (e) { deed(e); }',
 'by-then':                 'try { await Promise.resolve(1).then(() => { throw p; }); } catch (e) { deed(e); }',
 'to-a-catch-callback':     'await Promise.reject(p).catch(e => deed(e));',
 'to-the-second-callback':  'await Promise.reject(p).then(null, e => deed(e));',
 'by-an-async-function':    'async function thrower(v) { throw v; }\n  try { await thrower(p); } catch (e) { deed(e); }',
 'by-an-async-function-behind-an-await': 'async function thrower(v) { await 1; throw v; }\n  try { await thrower(p); } catch (e) { deed(e); }',
 'async-to-a-catch-callback': 'async function thrower(v) { throw v; }\n  await thrower(p).catch(e => deed(e));',
 'by-an-async-arrow':       'try { await (async v => { throw v; })(p); } catch (e) { deed(e); }',
 'by-an-async-method':      'class T { async m(v) { throw v; } }\n  try { await new T().m(p); } catch (e) { deed(e); }',
 'through-two-async':       'async function inner(v) { throw v; }\n  async function outer(v) { return await inner(v); }\n  try { await outer(p); } catch (e) { deed(e); }',
 'returned-rejected':       'async function inner(v) { throw v; }\n  async function outer(v) { return inner(v); }\n  try { await outer(p); } catch (e) { deed(e); }',
 'by-a-thenable':           'try { await { then(resolve, reject) { reject(p); } }; } catch (e) { deed(e); }',
 'by-a-thenable-that-throws': 'try { await { then() { throw p; } }; } catch (e) { deed(e); }',
 'by-promise-all':          'try { await Promise.all([Promise.reject(p)]); } catch (e) { deed(e); }',
 'by-promise-race':         'try { await Promise.race([Promise.reject(p)]); } catch (e) { deed(e); }',
 'by-promise-any':          'try { await Promise.any([Promise.reject(p)]); } catch (e) { deed(e.errors[0]); }',
 'by-all-settled':          'deed((await Promise.allSettled([Promise.reject(p)]))[0].reason);',
 'by-a-generator':          'function* g(v) { throw v; }\n  try { g(p).next(); } catch (e) { deed(e); }',
 'into-a-generator':        'function* g() { try { yield 1; } catch (e) { deed(e); } }\n  const it = g(); it.next(); it.throw(p);',
 'through-a-generator':     'function* g() { yield 1; }\n  const it = g(); it.next();\n  try { it.throw(p); } catch (e) { deed(e); }',
 'by-a-delegate':           'function* inner(v) { throw v; }\n  function* g(v) { yield* inner(v); }\n  try { g(p).next(); } catch (e) { deed(e); }',
 'into-a-delegate':         'function* inner() { try { yield 1; } catch (e) { deed(e); } }\n  function* g() { yield* inner(); }\n  const it = g(); it.next(); it.throw(p);',
 'by-a-generator-in-a-loop': 'function* g(v) { yield 1; throw v; }\n  try { for (const x of g(p)) count++; } catch (e) { deed(e); }',
 'by-an-async-generator':   'async function* g(v) { throw v; }\n  try { await g(p).next(); } catch (e) { deed(e); }',
 'by-for-await':            'async function* g(v) { yield 1; throw v; }\n  try { for await (const x of g(p)) count++; } catch (e) { deed(e); }',
 'into-an-async-generator': 'async function* g() { try { yield 1; } catch (e) { deed(e); } }\n  const it = g(); await it.next(); await it.throw(p);',
 'by-a-disposal':           'try { using r = { [Symbol.dispose]() { throw p; } }; } catch (e) { deed(e); }',
 'suppressed':              'try { using r = { [Symbol.dispose]() { throw p; } }; throw 1; } catch (e) { deed(e.error); }',
 'suppressing':             'try { using r = { [Symbol.dispose]() { throw 1; } }; throw p; } catch (e) { deed(e.suppressed); }',
 'as-a-cause':              'try { throw new Error("m", { cause: p }); } catch (e) { deed(e.cause); }',
 'as-a-field-of-an-error':  'class E extends Error { constructor(v) { super("m"); this.held = v; } }\n  try { throw new E(p); } catch (e) { deed(e.held); }',
 'in-a-list':               'try { throw [p]; } catch (e) { deed(e[0]); }',
 'in-a-record':             'try { throw { held: p }; } catch (e) { deed(e.held); }',
 'by-a-microtask':          'await new Promise(resolve => queueMicrotask(() => { try { throw p; } catch (e) { deed(e); } resolve(); }));',
 'by-a-timer':              'await new Promise(resolve => setTimeout(() => { try { throw p; } catch (e) { deed(e); } resolve(); }, 0));',
 'to-the-process':          'await new Promise(resolve => { process.once("uncaughtException", e => { deed(e); resolve(); }); setTimeout(() => { throw p; }, 0); });',
 'to-the-process-as-a-rejection': 'await new Promise(resolve => { process.once("unhandledRejection", e => { deed(e); resolve(); }); Promise.reject(p); });',
 'by-an-emitter':           'const emitter = new EventEmitter();\n  emitter.on("x", v => { throw v; });\n  try { emitter.emit("x", p); } catch (e) { deed(e); }',
 'as-an-error-event':       'const emitter = new EventEmitter();\n  try { emitter.emit("error", p); } catch (e) { deed(e); }',
 'by-eval-like-function':   'try { new Function("v", "throw v")(p); } catch (e) { deed(e); }',
 'without-a-binding':       'let kept;\n  function thrower(v) { kept = v; throw v; }\n  try { thrower(p); } catch { deed(kept); }',
 'by-a-label':              'out: try { throw p; } catch (e) { deed(e); break out; }',
 'in-a-loop':               'for (let i = 0; i < 2; i++) { try { if (i) throw p; } catch (e) { deed(e); } }',
 'by-a-switch':             'try { switch (count) { case 0: throw p; } } catch (e) { deed(e); }',
 'by-an-optional-call':     'const o = { m(v) { throw v; } };\n  try { o?.m?.(p); } catch (e) { deed(e); }',
 'by-super':                'class B { m(v) { throw v; } }\n  class T extends B { m(v) { super.m(v); } }\n  try { new T().m(p); } catch (e) { deed(e); }',
 'by-instanceof':           'const c = { [Symbol.hasInstance]() { throw p; } };\n  try { ({}) instanceof c; } catch (e) { deed(e); }',
 'by-in':                   'const o = new Proxy({}, { has() { throw p; } });\n  try { "x" in o; } catch (e) { deed(e); }',
 'by-spread-of-arguments':  'function thrower(...vs) { throw vs[0]; }\n  try { thrower(...[p]); } catch (e) { deed(e); }',
 'by-recursion':            'function down(n, v) { if (!n) throw v; down(n - 1, v); }\n  try { down(3, p); } catch (e) { deed(e); }',
}
deeds = {
 'stores':           'e.x = "s";',
 'deletes':          'delete e.x;',
 'adds':             'e.z = 1;',
 'defines-a-getter': 'Object.defineProperty(e, "x", { get() { return "g"; }, configurable: true });',
 'changes-the-prototype': 'Object.setPrototypeOf(e, Q.prototype);',
 'overrides-a-method': 'e.m = () => "own";',
 'freezes':          'Object.freeze(e);',
 'stores-by-a-made-up-key': 'e[["x"].join("")] = "k";',
 'assigns':          'Object.assign(e, { x: "a" });',
 'keeps':            'kept.push(e); later();',
}
uses = ['p.x + 1', 'typeof p.x', 'p.m()', 'Object.keys(p).join()', '(p.x = 5, p.x)']
count = 0
for road, body in roads.items():
    for deed, done in deeds.items():
        for number, use in enumerate(uses):
            lines = ['// Thrown %s; whoever catches it %s.' % (road.replace('-', ' '), deed.replace('-', ' '))]
            if 'EventEmitter' in body: lines.append('import { EventEmitter } from "node:events";')
            lines += ['class P { x = 1; y = 2; m() { return "P" + this.y; } }', 'class Q { m() { return "Q"; } }', 'let count = 0;', 'const kept = [];',
                      'function later() { kept[0].x = "l"; }', 'function deed(e) { try { %s } catch (error) { console.log(error.constructor.name); } }' % done, 'function use(p) { return %s; }' % use,
                      'async function road(p) {', '  ' + body, '}', 'const thrown = new P();', 'await road(thrown);', 'try { console.log(use(thrown)); } catch (error) { console.log(error.constructor.name); }']
            with open(os.path.join(out, '%s-%s-%d.mjs' % (road, deed, number)), 'w') as f:
                f.write('\n'.join(lines) + '\n')
            count += 1
print(count, 'programs')
